using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Controls.Primitives;
using Microsoft.Windows.Storage.Pickers;
using System.Security.Cryptography;
using System.Text.Json.Nodes;
using TrayAssistant_App.ViewModels;
namespace TrayAssistant_App;
public sealed partial class MainPage : Page
{
 public TrayViewModel Vm { get; } = new();
 private readonly DispatcherTimer timer = new() { Interval = TimeSpan.FromSeconds(1) };
 private bool loaded;
 public MainPage() { InitializeComponent(); Vm.ThemeChanged += index => RequestedTheme = index switch {1 => ElementTheme.Light,2 => ElementTheme.Dark,_ => ElementTheme.Default}; timer.Tick += async (_,_) => await Vm.RefreshAsync(); Unloaded += (_,_) => timer.Stop(); }
 private async void Page_Loaded(object sender,RoutedEventArgs e) { if(!loaded){loaded=true;await Vm.InitializeAsync();}timer.Start(); }
 private void Page_SizeChanged(object sender,SizeChangedEventArgs e) { if(ListColumn!=null) ListColumn.Width=new GridLength(e.NewSize.Width<850?260:330); }
 private void Nav_SelectionChanged(NavigationView sender,NavigationViewSelectionChangedEventArgs args) { if(IconsView==null)return;var tag=(args.SelectedItem as NavigationViewItem)?.Tag?.ToString();IconsView.Visibility=tag=="icons"?Visibility.Visible:Visibility.Collapsed;WindowsView.Visibility=tag=="windows"?Visibility.Visible:Visibility.Collapsed;SettingsView.Visibility=tag=="settings"?Visibility.Visible:Visibility.Collapsed;DiagnosticsView.Visibility=tag=="diagnostics"?Visibility.Visible:Visibility.Collapsed;PageHeading.Text=tag switch{"windows"=>"少一点窗口，多一点空间","settings"=>"让助手适合你的习惯","diagnostics"=>"运行状态",_=>"你的托盘，由你整理"};PageSubtitle.Text=tag switch{"windows"=>"收起窗口，随时回来。","settings"=>"从启动到外观，都由你决定。","diagnostics"=>"查看连接、事件与恢复状态。",_=>"藏好不常用的图标，留下你想看见的。"}; }
 private async void IconList_DragItemsCompleted(ListViewBase sender,DragItemsCompletedEventArgs args){try{int order=0;foreach(var row in Vm.Icons){var rule=(JsonObject)row.Rule.DeepClone();rule["location"]=row.Rule["placement"]!.GetValue<int>()==0?0:1;rule["order"]=order++;var r=await Vm.Pipe.RequestAsync("rule.apply",new(){["rule"]=rule});if(r["success"]?.GetValue<bool>()!=true)throw new IOException(r["detail"]?.GetValue<string>());}Vm.Status="顺序已应用到实际托盘";}catch(Exception ex){Vm.Status=ex.Message;}}
 private async void RefreshWindows_Click(object sender,RoutedEventArgs e){try{var result=await Vm.Pipe.RequestAsync("window.list");WindowsList.Children.Clear();foreach(var item in result["data"]!["windows"]!.AsArray()){var entry=item!.AsObject();var button=new Button{Content=entry["title"]!.GetValue<string>(),HorizontalAlignment=HorizontalAlignment.Stretch};button.Click+=async(_,_)=>{var r=await Vm.Pipe.RequestAsync("window.minimize",new(){["hwnd"]=entry["hwnd"]!.DeepClone(),["created"]=entry["created"]!.DeepClone()});Vm.WindowsStatus=r["detail"]?.GetValue<string>()??"";};WindowsList.Children.Add(button);}}catch(Exception ex){Vm.Status=ex.Message;}}
 private async void Export_Click(object sender,RoutedEventArgs e){try{var picker=new FileSavePicker(App.Window.AppWindow.Id){SuggestedFileName="托盘助手配置"};picker.FileTypeChoices.Add("助手配置",new List<string>{".json"});var file=await picker.PickSaveFileAsync();if(file==null)return;var r=await Vm.Pipe.RequestAsync("settings.read");var settings=(JsonObject)r["data"]!.DeepClone();var assets=new JsonObject();foreach(var rule in settings["rules"]!.AsArray())await Embed(rule!.AsObject(),assets);await Embed(settings["ownIcon"]!.AsObject(),assets);settings["assets"]=assets;await File.WriteAllTextAsync(file.Path,settings.ToJsonString(new(){WriteIndented=true}));Vm.Status="配置与图标已导出";}catch(Exception ex){Vm.Status=ex.Message;}}
 private static async Task Embed(JsonObject node,JsonObject assets){var path=node["asset"]?.GetValue<string>()??"";if(path.Length==0)return;var bytes=await File.ReadAllBytesAsync(path);var name=Convert.ToHexString(SHA256.HashData(bytes))+Path.GetExtension(path);assets[name]=Convert.ToBase64String(bytes);node["asset"]=name;}
 private async void Import_Click(object sender,RoutedEventArgs e){try{var picker=new FileOpenPicker(App.Window.AppWindow.Id);picker.FileTypeFilter.Add(".json");var file=await picker.PickSingleFileAsync();if(file==null)return;if(new FileInfo(file.Path).Length>64*1024*1024)throw new IOException("配置文件过大");var settings=JsonNode.Parse(await File.ReadAllTextAsync(file.Path))!.AsObject();if(settings["schema"]?.GetValue<int>()!=1)throw new IOException("配置版本不兼容");var assets=settings["assets"]?.AsObject()??new();var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"TrayIconAssistant","Assets");Directory.CreateDirectory(dir);foreach(var item in assets){if(Path.GetFileName(item.Key)!=item.Key)throw new IOException("图标资源路径无效");var bytes=Convert.FromBase64String(item.Value!.GetValue<string>());if(bytes.Length>32*1024*1024)throw new IOException("图标资源过大");var ext=Path.GetExtension(item.Key).ToLowerInvariant();if(!new[]{".ico",".png",".bmp",".jpg",".jpeg",".exe",".dll"}.Contains(ext))throw new IOException("不支持的图标格式");await File.WriteAllBytesAsync(Path.Combine(dir,item.Key),bytes);}foreach(var rule in settings["rules"]!.AsArray())Rewrite(rule!.AsObject(),dir,assets);Rewrite(settings["ownIcon"]!.AsObject(),dir,assets);settings.Remove("assets");var result=await Vm.Pipe.RequestAsync("settings.import",new(){["settings"]=settings});if(result["success"]?.GetValue<bool>()!=true)throw new IOException(result["detail"]?.GetValue<string>());Vm.Status="配置已导入";await Vm.InitializeAsync();}catch(Exception ex){Vm.Status=ex.Message;}}
 private static void Rewrite(JsonObject node,string dir,JsonObject assets){var name=node["asset"]?.GetValue<string>()??"";if(name.Length>0){if(!assets.ContainsKey(name))throw new IOException("缺少图标资源");node["asset"]=Path.Combine(dir,name);}}
}
